package io.github.otakukisaragishintaro.boundlesschatdiscord.ui;
import android.app.Activity;import android.app.AlertDialog;import android.app.Dialog;import android.text.InputType;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.Spinner;import android.widget.TextView;import android.widget.Switch;import android.widget.Toast;
import io.github.otakukisaragishintaro.boundlesschatdiscord.R;import io.github.otakukisaragishintaro.boundlesschatdiscord.core.Config;import io.github.otakukisaragishintaro.boundlesschatdiscord.core.OutboundButtonConfig;import java.util.ArrayList;import java.util.List;
/** Dialog-based manager for independent outbound language actions. */
public final class OutboundButtonsEditor{
 public interface Listener{void onChanged(List<OutboundButtonConfig> buttons);}private OutboundButtonsEditor(){}
 public static Dialog show(Activity a,List<OutboundButtonConfig> initial,String[] values,String[] labels,String defaultPrompt,Listener listener){
  List<OutboundButtonConfig> draft=new ArrayList<>(initial);LinearLayout content=column(a);content.setPadding(dp(a,18),dp(a,12),dp(a,18),dp(a,12));ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.addView(content);
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle(R.string.outbound_manage_title).setView(scroll).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.outbound_done,(d,w)->listener.onChanged(new ArrayList<>(draft))).create();
  Runnable[] refresh=new Runnable[1];refresh[0]=()->{content.removeAllViews();TextView intro=new TextView(a);intro.setText(a.getString(R.string.outbound_intro,OutboundButtonConfig.MAX_BUTTONS));intro.setTextSize(13);content.addView(intro,match());
   for(int i=0;i<draft.size();i++){final int index=i;OutboundButtonConfig item=draft.get(i);LinearLayout row=column(a);row.setPadding(0,dp(a,10),0,dp(a,10));TextView summary=new TextView(a);summary.setText(a.getString(R.string.outbound_button_summary,item.label,item.targetLanguage,item.systemPrompt.length()));summary.setTextSize(14);row.addView(summary,match());LinearLayout actions=new LinearLayout(a);actions.setOrientation(LinearLayout.HORIZONTAL);
    Button edit=new Button(a);edit.setText(R.string.outbound_edit);edit.setOnClickListener(v->editOne(a,draft,index,values,labels,defaultPrompt,refresh[0]));actions.addView(edit,weighted());
    Button del=new Button(a);del.setText(R.string.outbound_delete);del.setOnClickListener(v->{AlertDialog confirm=new AlertDialog.Builder(a).setTitle(R.string.outbound_delete_title).setMessage(a.getString(R.string.outbound_delete_confirm,item.label)).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.outbound_delete,(d,w)->{draft.remove(index);refresh[0].run();}).create();confirm.show();SettingsUiStyle.styleDialog(a,confirm);});actions.addView(del,weighted());row.addView(actions,match());content.addView(row,match());}
   Button add=new Button(a);add.setText(R.string.outbound_add);add.setEnabled(draft.size()<OutboundButtonConfig.MAX_BUTTONS);add.setOnClickListener(v->{if(draft.size()<OutboundButtonConfig.MAX_BUTTONS)editOne(a,draft,-1,values,labels,defaultPrompt,refresh[0]);});content.addView(add,match());
   if(draft.isEmpty()){TextView empty=new TextView(a);empty.setText(R.string.outbound_empty);content.addView(empty,match());}};
  refresh[0].run();dialog.show();SettingsUiStyle.styleDialog(a,dialog);return dialog;
 }
 private static void editOne(Activity a,List<OutboundButtonConfig> draft,int index,String[] values,String[] labels,String defaultPrompt,Runnable refresh){
  boolean adding=index<0;OutboundButtonConfig old=adding?null:draft.get(index);LinearLayout form=column(a);form.setPadding(dp(a,18),dp(a,8),dp(a,18),dp(a,8));
  TextView title=new TextView(a);title.setText(R.string.outbound_label_title);form.addView(title,match());EditText label=new EditText(a);label.setSingleLine(true);label.setHint(R.string.outbound_label_hint);label.setText(adding?"":old.label);label.setInputType(InputType.TYPE_CLASS_TEXT);form.addView(label,match());
  TextView languageTitle=new TextView(a);languageTitle.setText(R.string.outbound_language_title);form.addView(languageTitle,match());Spinner language=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);language.setAdapter(adapter);int selected=2;if(!adding)for(int i=0;i<values.length;i++)if(values[i].equals(old.targetLanguage))selected=i;language.setSelection(selected);form.addView(language,match());
  final String[] prompt={adding?defaultPrompt:old.systemPrompt};Switch customPrompt=new Switch(a);customPrompt.setText("启用此按钮的专属提示词（默认关闭）");customPrompt.setShowText(false);customPrompt.setChecked(!io.github.otakukisaragishintaro.boundlesschatdiscord.core.LanguagePromptConfig.isDefaultPrompt(prompt[0],adding?Config.DEF_SEND_TARGET_LANG:old.targetLanguage,true));form.addView(customPrompt,match());Button promptButton=new Button(a);promptButton.setText(R.string.outbound_prompt_edit);promptButton.setVisibility(customPrompt.isChecked()?android.view.View.VISIBLE:android.view.View.GONE);promptButton.setOnClickListener(v->editPrompt(a,prompt,promptButton));form.addView(promptButton,match());customPrompt.setOnCheckedChangeListener((button,checked)->{promptButton.setVisibility(checked?android.view.View.VISIBLE:android.view.View.GONE);if(!checked)prompt[0]=Config.DEF_SEND_SYSTEM_PROMPT;});
  AlertDialog editor=new AlertDialog.Builder(a).setTitle(adding?R.string.outbound_add_title:R.string.outbound_edit_title).setView(form).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.outbound_save,null).create();
  editor.setOnShowListener(d->editor.getButton(-1).setOnClickListener(v->{int pos=language.getSelectedItemPosition();if(pos<0||pos>=values.length){Toast.makeText(a,R.string.outbound_choose_language,Toast.LENGTH_SHORT).show();return;}String target=values[pos];String visible=label.getText().toString().trim();if(visible.isEmpty())visible=OutboundButtonConfig.defaultLabel(target);try{String selectedPrompt=customPrompt.isChecked()?prompt[0]:Config.DEF_SEND_SYSTEM_PROMPT;OutboundButtonConfig updated=new OutboundButtonConfig(adding?java.util.UUID.randomUUID().toString():old.id,visible,target,selectedPrompt);if(adding)draft.add(updated);else draft.set(index,updated);editor.dismiss();refresh.run();}catch(IllegalArgumentException invalid){Toast.makeText(a,invalid.getMessage(),Toast.LENGTH_LONG).show();}}));
  editor.show();SettingsUiStyle.styleDialog(a,editor);
 }
 private static void editPrompt(Activity a,String[] prompt,Button owner){LinearLayout form=column(a);form.setPadding(dp(a,18),dp(a,8),dp(a,18),dp(a,8));EditText input=new EditText(a);input.setMinLines(8);input.setGravity(android.view.Gravity.TOP|android.view.Gravity.START);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setText(prompt[0]);form.addView(input,match());Button reset=new Button(a);reset.setText(R.string.button_restore_default_prompt);reset.setOnClickListener(v->input.setText(Config.DEF_SEND_SYSTEM_PROMPT));form.addView(reset,match());AlertDialog d=new AlertDialog.Builder(a).setTitle(R.string.outbound_prompt_title).setView(form).setNegativeButton(android.R.string.cancel,null).setPositiveButton(android.R.string.ok,(x,w)->{prompt[0]=input.getText().toString();owner.setText(a.getString(R.string.outbound_prompt_edit_length,prompt[0].length()));}).create();d.show();SettingsUiStyle.styleDialog(a,d);}
 private static LinearLayout column(Activity a){LinearLayout l=new LinearLayout(a);l.setOrientation(LinearLayout.VERTICAL);return l;}private static LinearLayout.LayoutParams match(){return new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);}private static LinearLayout.LayoutParams weighted(){return new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f);}private static int dp(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}
}